function validate([preorder]) {
  if (typeof preorder !== 'string' || preorder.length < 1 || preorder.length > 10000) return 'preorder needs 1 to 10000 characters.';
  for (const item of preorder.split(',')) {
    if (!/^(#|0|[1-9]\d?|100)$/.test(item)) return 'Each comma-separated item must be # or a whole number from 0 to 100.';
  }
  return null;
}

