function isValidSerialization(preorder) {
  const tokens = preorder.split(',');
  let slots = 1;

  for (const token of tokens) {
    if (slots === 0) {
      return false;
    }
    slots--;
    if (token !== '#') {
      slots += 2;
    }
  }
  return slots === 0;
}

