function isValidSerialization(preorder) {
  // Repeatedly collapse a finished subtree "value,#,#" into a single "#".
  const stack = [];
  for (const token of preorder.split(',')) {
    stack.push(token);
    while (stack.length >= 3 && stack[stack.length - 1] === '#' && stack[stack.length - 2] === '#' && stack[stack.length - 3] !== '#') {
      stack.splice(stack.length - 3, 3, '#');
    }
  }
  return stack.length === 1 && stack[0] === '#';
}

