function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const value = () => String(rand() < 0.1 ? (rand() < 0.5 ? 0 : 100) : pick(101));
  const token = () => (rand() < 0.5 ? '#' : value());
  let tokens = [];
  if (size === 'small' && rand() < 0.15) {
    const length = 1 + pick(6);
    for (let i = 0; i < length; i++) tokens.push(token());
    return [tokens.join(',')];
  }
  // A valid serialization: a number opens two slots, '#' closes one, and it ends when no slot is open.
  let remaining = size === 'large' ? 1200 + pick(400) : pick(7);
  const chance = 0.3 + rand() * 0.6;
  let slots = 1;
  while (slots > 0) {
    if (remaining > 0 && (slots === 1 || rand() < chance)) {
      tokens.push(value());
      slots++;
      remaining--;
    } else {
      tokens.push('#');
      slots--;
    }
  }
  const r = rand();
  if (r < 0.45) {
    // keep it valid
  } else if (r < 0.55) {
    tokens.push(token());
  } else if (r < 0.65 && tokens.length > 1) {
    tokens.pop();
  } else if (r < 0.75 && tokens.length > 1) {
    tokens.splice(pick(tokens.length), 1);
  } else if (r < 0.85) {
    tokens.splice(pick(tokens.length + 1), 0, token());
  } else {
    const i = pick(tokens.length);
    tokens[i] = tokens[i] === '#' ? value() : '#';
  }
  return [tokens.join(',')];
}
